function videoToc(ctx) {
  return [{ title: ctx.book.name || '正片', url: ctx.book.bookUrl }];
}
function videoContent(ctx) {
  var url = ctx.chapter.url || ctx.book.bookUrl;
  var cacheKey = 'video:' + String(url);
  try { var cached = cache.get(cacheKey); if (cached) return cached; } catch (e) {}
  var r = http.get(url, { timeout: 8000 });
  if (!r || !r.ok) throw new Error('播放页请求失败：' + (r ? (r.error || r.status) : 'unknown'));
  var raw = native.sel('@css:div.dplayer@data-config', r.body);
  if (!raw) {
    var m = String(r.body).match(/data-config=\'([^\']+)\'/);
    if (m) raw = m[1];
  }
  if (!raw) throw new Error('播放页没有找到视频配置');
  raw = String(raw).replace(/&amp;/g, '&');
  var cfg = JSON.parse(raw);
  var v = (cfg && cfg.video && cfg.video.url) ? cfg.video.url : '';
  if (!v) throw new Error('没有取到视频直链');
  var out = { video: v, videoPage: url };
  try { cache.put(cacheKey, out, 300); } catch (e) {}
  return out;
}

// ---- 搜索自翻页（book-source 技能 searchfix 生成，形态：html）----
// 宿主搜索页只请求第 1 页，所以这里自己按页取，每取到一页立刻 ui.emitSearch 交出；
// 列表边搜边长。宿主若已经支持下滑翻页并传来 ctx.page > 1，则只取那一页（宿主按 bookUrl 去重）。
function sxSearch(ctx) {
  var kw = String(ctx.key == null ? '' : ctx.key).replace(/^\s+|\s+$/g, '');
  if (!kw) return '';
  var enc = encodeURIComponent(kw);
  var v = (ctx && ctx.vars) || {};
  var srv = String(v.server || v.base || v.site || (ctx && ctx.source && ctx.source.url) || '').replace(/\/+$/, '');
  var start = Math.max(1, Number(ctx.page || 1));
  var end = start === 1 ? 4 : start;
  var html = '', prev = '', got = 0;
  for (var p = start; p <= end; p++) {
    var url = String('{{vars.server}}/search/{{urlencode(key)}}/').replace(/\/+$/, '') + (p > 1 ? '?page=' + p : '');
    // 模板占位符在脚本里是普通字符串，宿主不会替换，这里自己展开
    url = url.replace(/\{\{\s*vars\.([A-Za-z0-9_]+)\s*\}\}/g, function (_, k) { return String(v[k] || ''); })
             .replace(/\{\{\s*server\s*\}\}/g, srv)
             .replace(/\{\{\s*source\.url\s*\}\}/g, srv)
             .replace(/\{\{\s*urlencode\(\s*key\s*\)\s*\}\}/g, enc)
             .replace(/\{\{\s*key\s*\}\}/g, kw);
    var r;
    try {
      r = http.request({ url: url, headers: {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36'} });
    } catch (e) {
      if (p === start) throw new Error('搜索请求失败：' + (e && e.message ? e.message : e));
      break;
    }
    if (!r || !r.ok || !r.body) break;
    var body = String(r.body);
    if (body === prev) break;   // 站点忽略页码：正文与上一页相同
    prev = body;
    var n = native.selAll('@css:article a@href', body).length;
    if (n === 0) break;
    if (n < 0 && p > start) break;   // 计数规则不适用时，第 2 页起不再硬翻
    got += (n > 0 ? n : 1);
    html += body;
    ui.emitSearch(page(body, url));
  }
  if (!got) {
    throw new Error('搜索「' + kw + '」没有取到结果：检查列表规则、站点是否改版，或该关键词确实无结果');
  }
  return html;
}

// ---- 搜索自翻页（book-source 技能 searchfix 生成，形态：html）----
// 宿主搜索页只请求第 1 页，所以这里自己按页取，每取到一页立刻 ui.emitSearch 交出；
// 列表边搜边长。宿主若已经支持下滑翻页并传来 ctx.page > 1，则只取那一页（宿主按 bookUrl 去重）。
function sxSearch(ctx) {
  var kw = String(ctx.key == null ? '' : ctx.key).replace(/^\s+|\s+$/g, '');
  if (!kw) return '';
  var enc = encodeURIComponent(kw);
  var v = (ctx && ctx.vars) || {};
  var srv = String(v.server || v.base || v.site || (ctx && ctx.source && ctx.source.url) || '').replace(/\/+$/, '');
  var start = Math.max(1, Number(ctx.page || 1));
  var end = start === 1 ? 4 : start;
  var html = '', prev = '', got = 0;
  for (var p = start; p <= end; p++) {
    var url = (p > 1 ? String('{{server}}/search-result/{{urlencode(key)}}/{{page}}/').replace(/\{\{\s*page\s*\}\}/g, String(p)) : '{{server}}/search-result/{{urlencode(key)}}');
    // 模板占位符在脚本里是普通字符串，宿主不会替换，这里自己展开
    url = url.replace(/\{\{\s*vars\.([A-Za-z0-9_]+)\s*\}\}/g, function (_, k) { return String(v[k] || ''); })
             .replace(/\{\{\s*server\s*\}\}/g, srv)
             .replace(/\{\{\s*source\.url\s*\}\}/g, srv)
             .replace(/\{\{\s*urlencode\(\s*key\s*\)\s*\}\}/g, enc)
             .replace(/\{\{\s*key\s*\}\}/g, kw);
    var r;
    try {
      r = http.get(url);
    } catch (e) {
      if (p === start) throw new Error('搜索请求失败：' + (e && e.message ? e.message : e));
      break;
    }
    if (!r || !r.ok || !r.body) break;
    var body = String(r.body);
    if (body === prev) break;   // 站点忽略页码：正文与上一页相同
    prev = body;
    var n = native.selAll('@css:.dm-card', body).length;
    if (n === 0) break;
    if (n < 0 && p > start) break;   // 计数规则不适用时，第 2 页起不再硬翻
    got += (n > 0 ? n : 1);
    html += body;
    ui.emitSearch(page(body, url));
  }
  if (!got) {
    throw new Error('搜索「' + kw + '」没有取到结果：检查列表规则、站点是否改版，或该关键词确实无结果');
  }
  return html;
}

function tocChapters(ctx) {
  var raw = String(ctx.book && ctx.book.bookUrl ? ctx.book.bookUrl : '');
  var url = raw.split('#')[0];
  var ck = 'page:' + url;
  var body = String(cache.get(ck) || '');
  if (!body) {
    var r = http.get(url, { timeout: 10000 });
    if (!r.ok) throw new Error('获取目录失败：' + (r.error || ('HTTP ' + r.status)));
    body = r.body || '';
    if (body) cache.put(ck, body, 180);
  }
  var eps = native.selAll('@css:.eps .ep@html', body);
  var out = [];
  var i;
  if (eps && eps.length) {
    for (i = 0; i < eps.length; i++) {
      var href = native.sel('@css:a@href', eps[i]) || '';
      if (!href) continue;
      var t = String(native.sel('@css:a@text', eps[i]) || '').replace(/\s+/g, '');
      if (!t) t = String(i + 1);
      out.push({ title: '第' + t + '集', url: href });
    }
  }
  if (out.length === 0) {
    var re = /class="ep"[^>]*href="([^"]+)"/g;
    var m;
    var n = 0;
    while ((m = re.exec(body)) !== null) {
      n = n + 1;
      out.push({ title: '第' + n + '集', url: m[1] });
    }
  }
  if (out.length === 0) {
    out.push({ title: '单集', url: url });
  }
  return out;
}

function videoPlay(ctx) {
  var raw = String(ctx.chapter && ctx.chapter.url ? ctx.chapter.url : '');
  var url = raw.split('#')[0];
  var ck = 'play:' + url;
  var body = String(cache.get(ck) || '');
  if (!body) {
    var r = http.get(url, { timeout: 10000 });
    if (!r.ok) throw new Error('获取播放页失败：' + (r.error || ('HTTP ' + r.status)));
    body = String(r.body || '');
    if (body) cache.put(ck, body, 180);
  }
  body = body.replace(/\\\//g, '/');
  var m = body.match(/"contentUrl"\s*:\s*"([^"]+)"/);
  var v = '';
  if (m) v = m[1];
  if (!v) {
    var m2 = body.match(/https:\/\/m3u8[^"' ]+\.m3u8/);
    if (m2) v = m2[0];
  }
  if (!v) throw new Error('没有取到视频直链');
  return { video: v, videoPage: url };
}

function unesc(u) {
  return String(u).split('\\/').join('/');
}
function pickVideo(t) {
  var pats = [/video_url\s*[:=]\s*'([^']+)'/, /video_url\s*[:=]\s*"([^"]+)"/, /"video_url"\s*:\s*"([^"]+)"/, /(https?:\/\/[^"'\s<>]+\.m3u8[^"'\s<>]*)/, /(https?:\/\/[^"'\s<>]+\.mp4[^"'\s<>]*)/];
  var i, m;
  for (i = 0; i < pats.length; i++) {
    m = String(t || '').match(pats[i]);
    if (m && m[1]) return unesc(m[1]);
  }
  return '';
}
function playUrl(ctx) {
  var url = (ctx.chapter && ctx.chapter.url) ? ctx.chapter.url : ((ctx.book && ctx.book.bookUrl) ? ctx.book.bookUrl : '');
  var base = String(ctx.source.url || 'http://www.rbw203.com').replace(/\/+$/, '');
  var m = String(url).match(/\/videos\/(\d+)/);
  var id = m ? m[1] : '';
  var link = '';
  if (id) {
    link = cache.get('play_' + id) || '';
    if (!link) {
      var e = http.get(base + '/embed/' + id, { timeout: 9000 });
      if (e.ok) link = pickVideo(e.body);
    }
  }
  if (!link) {
    var r = http.get(url, { timeout: 9000 });
    if (r.ok) link = pickVideo(r.body);
  }
  if (!link) throw new Error('没有取到播放直链：该视频可能显示「游客试看已达上限」或站点限流，请稍后重试或改用网页播放');
  if (id) cache.put('play_' + id, link, 3600);
  return { video: link, videoPage: url };
}

function decCover(bytes, ctx) {
  return image.decrypt('AES/ECB/NoPadding', bytes, '4a756937582363646c654e5e33655a62');
}

function hqCards(body, base) {
  var nodes = native.selAll('@css:.module-item@html', body);
  var out = [], i;
  for (i = 0; i < nodes.length; i++) {
    var href = native.sel('@css:.module-item-title@href', nodes[i]) || '';
    var name = (native.sel('@css:.module-item-title@text', nodes[i]) || '').replace(/\s+/g, ' ').trim();
    if (!href || !name) continue;
    if (href.charAt(0) === '/') href = base + href;
    var cover = native.sel('@css:img@data-cover', nodes[i]) || '';
    out.push({ name: name, bookUrl: href, coverUrl: cover, type: 'video' });
  }
  return out;
}

function exploreList(ctx) {
  var base = (ctx.vars && ctx.vars.server) || ctx.source.url;
  base = String(base).replace(/\/+$/, '');
  var path = ctx.url || '';
  if (path.indexOf('http') !== 0) path = base + path;
  var page = Number(ctx.page) || 1;
  var key = 'ex_' + path;
  var st = cache.get(key);
  var start = 1, curLink = null, items = [], p, u, r, m;
  if (st && st.page) {
    if (st.page === page) return st.items || [];
    if (st.page < page && !st.next) return [];
    if (st.page < page) { start = st.page + 1; curLink = st.next; }
  }
  for (p = start; p <= page; p++) {
    u = curLink || path;
    if (u.indexOf('http') !== 0) u = base + u;
    r = http.get(u, { timeout: 8000 });
    if (!r.ok) throw new Error('HTTP ' + r.status + (r.error ? ' ' + r.error : ''));
    items = hqCards(r.body, base);
    m = String(r.body).match(/<script[^>]*name="cc"[^>]*>([^<]*)<\/script>/i);
    curLink = m ? m[1].trim() : '';
    if (!curLink || curLink === 'fail') {
      cache.put(key, { page: p, items: items, next: '' }, 600);
      return p === page ? items : [];
    }
    cache.put(key, { page: p, items: items, next: curLink }, 600);
  }
  return items;
}

function hqToc(ctx) {
  var url = (ctx.book && ctx.book.bookUrl) || '';
  var name = (ctx.book && ctx.book.name) || '正片';
  return [{ title: name, url: url }];
}

function hqVideo(html) {
  var s = String(html || '');
  var m = s.match(/[?&]url=(https?:\/\/[^"'\s<>]+?\.m3u8)/i);
  if (m) return m[1];
  m = s.match(/https?:\/\/[^"'\s<>]+?\.m3u8/i);
  return m ? m[0] : '';
}

var ALS_SITE = 'https://www.alicesw.com';
var ALS_LINES = ['https://www.alicesw.com', 'https://www.alicesw4.homes', 'https://www.alicesw2.homes', 'https://www.alicesw3.homes'];
var ALS_ROAD = 'https://xn--vcsx64d.asw4.cc/';

function alsNorm(u) {
  var s = String(u || '').replace(/^\s+|\s+$/g, '');
  if (!s) return '';
  if (s.indexOf('//') === 0) s = 'https:' + s;
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s.replace(/^\/+/, '');
  var m = /^(https?:\/\/[^\/?#]+)/i.exec(s);
  return m ? m[1].replace(/\/+$/, '') : '';
}

function alsAdd(list, u) {
  var n = alsNorm(u);
  if (n && list.indexOf(n) < 0) list.push(n);
}

function alsCachedLines() {
  try {
    var c = cache.get('als_lines');
    if (c) {
      var p = JSON.parse(c);
      if (p && p.length) return p;
    }
  } catch (e) {}
  return [];
}

function alsLineOptions(ctx) {
  var out = [];
  for (var i = 0; i < ALS_LINES.length; i++) alsAdd(out, ALS_LINES[i]);
  var cached = alsCachedLines();
  for (var j = 0; j < cached.length; j++) alsAdd(out, cached[j]);
  try { alsAdd(out, vars.get('server')); } catch (e) {}
  var best = '';
  try { best = alsNorm(cache.get('als_best')); } catch (e) {}
  if (best && out.indexOf(best) >= 0) {
    out.splice(out.indexOf(best), 1);
    out.unshift(best);
  }
  return out.length ? out : ALS_LINES;
}

function alsFetchLines(ctx) {
  var road = '';
  try { road = alsNorm(vars.get('road')); } catch (e) {}
  if (!road) road = ALS_ROAD;
  var r = http.get(road, { timeout: 12000, headers: { 'Accept': 'text/html,application/xhtml+xml,*/*;q=0.8' } });
  if (!r.ok || !r.body) return '✖ 发布页读取失败：' + (r.error || r.status || road);
  var out = [];
  var links = [];
  var m;
  var re = /jump\(\s*['"]([A-Za-z0-9+\/=]+)['"]\s*\)/g;
  while ((m = re.exec(r.body)) != null) links.push(m[1]);
  if (links.length) {
    try { alsAdd(out, native.unbase64(links[0])); } catch (e) {}
    for (var i = 1; i < links.length; i++) {
      var backup = '';
      try { backup = alsNorm(native.unbase64(links[i])); } catch (e) { continue; }
      if (!backup) continue;
      var r2 = http.get(backup, { timeout: 12000 });
      if (!r2.ok || !r2.body) continue;
      var b = /id=["']redirectButton["'][^>]*href=["']([^"']+)["']/i.exec(r2.body);
      if (!b) b = /href=["']([^"']+)["'][^>]*id=["']redirectButton["']/i.exec(r2.body);
      if (!b) continue;
      var target = alsNorm(b[1]) || alsNorm(backup + '/' + String(b[1]).replace(/^\/+/, ''));
      if (!target) continue;
      var r3 = http.get(target, { timeout: 12000 });
      if (!r3.ok || !r3.body) continue;
      var m3;
      var re3 = /u\d+\s*=\s*r\(["']([^"']+)["']\)/g;
      while ((m3 = re3.exec(r3.body)) != null) {
        alsAdd(out, String(m3[1]).split('').reverse().join(''));
      }
    }
  }
  if (!out.length) return '✖ 未从发布页解析到线路，请在设置里手动选择';
  cache.put('als_lines', JSON.stringify(out), 3600);
  return '✔ 获取到 ' + out.length + ' 条线路：' + out.map(function (x) { return x.replace('https://', ''); }).join(' · ');
}

function alsSpeedTest(ctx) {
  var list = alsLineOptions(ctx);
  var alive = [];
  var note = [];
  for (var i = 0; i < list.length; i++) {
    var t0 = new Date().getTime();
    var r = http.get(list[i] + '/', { timeout: 4000 });
    var ms = new Date().getTime() - t0;
    var ok = r.ok && r.body && r.body.indexOf('爱丽丝书屋') >= 0;
    note.push(list[i].replace('https://', '') + (ok ? ' ' + ms + 'ms' : ' 不可达'));
    if (ok) alive.push({ url: list[i], ms: ms });
  }
  if (!alive.length) return '✖ 所有线路都不可达\n' + note.join('\n');
  alive.sort(function (a, b) { return a.ms - b.ms; });
  vars.set('server', alive[0].url);
  cache.put('als_best', alive[0].url, 3600);
  try { ui.refreshExplore(); } catch (e) {}
  return '⚡ 已切换到 ' + alive[0].url.replace('https://', '') + '（' + alive[0].ms + 'ms）\n' + note.join('\n');
}

function alsResetLines(ctx) {
  vars.set('server', ALS_SITE);
  try { ui.refreshExplore(); } catch (e) {}
  return '✔ 已恢复默认线路 ' + ALS_SITE;
}

