  let t = stripHtml(html)
  let out = []
  for line in split(t, '\n') {
    let s = trim(line)
    if (s != '' && !contains(s, '加入书签')) { push(out, s) }
  }
  return join(out, '\n')
}

fn clean(html) {
  let t = stripHtml(html)
  let out = []
  for line in split(t, '\n') {
    let s = trim(line)
    if (s != '' && !contains(s, '天才一秒记住') && !contains(s, '最快更新') && !contains(s, '最新网址') && !contains(s, '无广告') && !contains(s, '正在手打中') && !contains(s, '报送') && !contains(s, '本章完')) {
      push(out, s)
    }
  }
  return join(out, '\n')
}

