function searchComics(ctx) {
  var all = [], seen = {}, pages = 0;
  for (var p = 1; p <= 3; p++) {
    var r = http.get('/api/v1/search?keyword=' + encodeURIComponent(ctx.key) + '&type=comic&page=' + p + '&pageSize=50', { headers: { Accept: 'application/json', Origin: 'https://bikahub.net', Referer: 'https://bikahub.net/' }, retry: { times: 3, onStatus: [429, 500, 502, 503, 504], backoff: 'exp', base: 1000, maxDelay: 8000, respectRetryAfter: true } });
    if (!r.ok) break;
    var j;
    try { j = r.json(); } catch (e) { break; }
    var items = (j.data && j.data.comics && j.data.comics.items) || [];
    if (!items.length) break;
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      if (!seen[it.id]) { seen[it.id] = 1; all.push(it); }
    }
    pages++;
    if (all.length >= 60) break;
