// ---- 搜索自翻页（book-source 技能 searchfix 生成，形态：html）----
// 宿主搜索页只请求第 1 页，所以这里自己按页取，每取到一页立刻 ui.emitSearch 交出；
// 列表边搜边长。宿主若已经支持下滑翻页并传来 ctx.page > 1，则只取那一页（宿主按 bookUrl 去重）。
function sxSearch(ctx) {
  var kw = String(ctx.key == null ? '' : ctx.key).replace(/^\s+|\s+$/g, '');
  if (!kw) return '';
  var enc = encodeURIComponent(kw);
  var v = (ctx && ctx.vars) || {};
  var srv = String(v.server || v.base || v.site || (ctx && ctx.source && ctx.source.url) || '').replace(/\/+$/, '');
  var start = Math.max(1, Number(ctx.page || 1));
  var end = start === 1 ? 4 : start;
  var html = '', prev = '', got = 0;
  for (var p = start; p <= end; p++) {
    var url = String('/manga-search/{{urlencode(key)}}/page/') + String(p) + '';
    // 模板占位符在脚本里是普通字符串，宿主不会替换，这里自己展开
    url = url.replace(/\{\{\s*vars\.([A-Za-z0-9_]+)\s*\}\}/g, function (_, k) { return String(v[k] || ''); })
             .replace(/\{\{\s*server\s*\}\}/g, srv)
             .replace(/\{\{\s*source\.url\s*\}\}/g, srv)
             .replace(/\{\{\s*urlencode\(\s*key\s*\)\s*\}\}/g, enc)
             .replace(/\{\{\s*key\s*\}\}/g, kw);
    var r;
    try {
      r = http.get(url);
    } catch (e) {
      if (p === start) throw new Error('搜索请求失败：' + (e && e.message ? e.message : e));
      break;
    }
    if (!r || !r.ok || !r.body) break;
    var body = String(r.body);
    if (body === prev) break;   // 站点忽略页码：正文与上一页相同
    prev = body;
    var n = native.selAll('@css:li.vodlist_item', body).length;
    if (n === 0) break;
    if (n < 0 && p > start) break;   // 计数规则不适用时，第 2 页起不再硬翻
    got += (n > 0 ? n : 1);
    html += body;
    ui.emitSearch(page(body, url));
  }
  if (!got) {
    throw new Error('搜索「' + kw + '」没有取到结果：检查列表规则、站点是否改版，或该关键词确实无结果');
  }
  return html;
}

