var DY_BASE = 'https://123.diyidm.com';
var DY_UA = 'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';

function dyAbs(url) {
  var u = String(url == null ? '' : url).trim();
  if (!u) return '';
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.charAt(0) !== '/') u = '/' + u;
  return DY_BASE + u;
}

function dyGet(url) {
  var cacheKey = 'dy:' + String(url);
  try { var cached = cache.get(cacheKey); if (cached) return String(cached); } catch (e) {}
  var last = '';
  for (var attempt = 0; attempt < 2; attempt++) {
    try {
      var r = http.get(url, {
        headers: {
          'User-Agent': DY_UA,
          'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
          'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
          'Referer': DY_BASE + '/'
        },
        timeout: 9000
      });
      if (r.ok) {
        var body = String(r.body == null ? '' : r.body);
        if (body.length > 500) { try { cache.put(cacheKey, body, 300); } catch (e) {} return body; }
        last = '响应过短（' + body.length + ' 字节）';
      } else {
        last = 'HTTP ' + r.status + ' ' + (r.error || '');
      }
    } catch (e) {
      last = (e && e.message) || String(e);
    }
    if (attempt === 0) {
      try { sleep(400); } catch (e2) {}
    }
  }
  throw new Error('请求失败：' + last + ' ' + url);
