function hdNorm(u) {
  var s = String(u || '').replace(/^\s+|\s+$/g, '');
  if (!s) return '';
  if (s.indexOf('http') !== 0) s = 'https://' + s.replace(/^\/+/, '');
  return s.replace(/\/+$/, '');
}

function hdAdd(out, u) {
  u = hdNorm(u);
  if (u && out.indexOf(u) < 0) out.push(u);
}

function hdMerged() {
  var out = [];
  var i;
  for (i = 0; i < HD_LINES.length; i++) hdAdd(out, HD_LINES[i]);
  try {
    var c = cache.get('hdLines');
    if (c) {
      var p = JSON.parse(c);
      for (i = 0; i < p.length; i++) hdAdd(out, p[i]);
    }
  } catch (e) {}
  try { hdAdd(out, vars.get('server')); } catch (e) {}
  return out;
}

