  if (!b) return false;
  return b.length > 20000 && (b.indexOf('stui-vodlist') >= 0 || b.indexOf('\u82b1\u90fd') >= 0);
}

function hdPick(body) {
  var out = [];
  if (!body) return out;
  var m;
  var re1 = /https?:\/\/hd\.[a-z0-9.-]+/gi;
  while ((m = re1.exec(body)) !== null) {
    var h = String(m[0]).toLowerCase();
    if (h.indexOf('hdfby') >= 0 || h.indexOf('hdys.top') >= 0) continue;
    hdAdd(out, h);
  }
  var re2 = /"https:\/\/"\s*\+\s*\w+\s*\+\s*"\.([a-zA-Z0-9.-]+)"/g;
  while ((m = re2.exec(body)) !== null) {
    var d = String(m[1]).toLowerCase();
    if (d.indexOf('hdfby') >= 0 || d.indexOf('hdys.top') >= 0) continue;
    if (d.length < 5 || d.length > 30) continue;
