function hgBooks(line, body) {
  var cards = native.selAll("@css:.hg-card-grid .hg-drama-card@html", body);
  var out = [], seen = {};
  for (var i = 0; i < cards.length; i++) {
    var c = cards[i];
    var href = native.sel("@css:.hg-drama-card__title a@href", c) || "";
    var name = native.sel("@css:.hg-drama-card__title a@text", c) || "";
    name = name.replace(/全集在线观看/g, "").replace(/^\s+|\s+$/g, "");
    if (!href || !name) continue;
    if (href.charAt(0) === "/") href = line + href;
    if (seen[href]) continue;
    seen[href] = 1;
    var cover = native.sel("@css:.hg-drama-card__cover img@data-src", c) || "";
    if (!cover) cover = line + HG_DEFAULT_COVER;
    var kind = c.match(/data-track-type-name="([^"]*)"/);
    out.push({
      name: name,
      bookUrl: href,
      coverUrl: cover,
      intro: native.sel("@css:.hg-drama-card__desc@text", c) || "",
      kind: kind ? kind[1] : "",
