  return hgBooks(hit.line, hit.body);
}

function hgActPing() {
  var reqs = [], i, good = [], rs = [];
  for (i = 0; i < HG_LINES.length; i++) {
    reqs.push({ url: HG_LINES[i] + "/ai-duanju/", timeout: 5000, headers: hgHdr(HG_LINES[i]) });
  }
  if (typeof http.all === "function") {
    rs = http.all(reqs, { concurrency: 8, timeout: 5000 });
  } else {
    for (i = 0; i < reqs.length; i++) rs.push(http.get(reqs[i].url, { timeout: 5000, headers: reqs[i].headers }));
  }
  for (i = 0; i < rs.length; i++) if (hgOk(rs[i])) good.push(HG_LINES[i]);
  if (!good.length) return "测速失败：" + HG_LINES.length + " 条线路全部不可用";
  var best = good[0], bestMs = 1e12;
  for (i = 0; i < good.length && i < 6; i++) {
    var t0 = Date.now();
    var rr = http.get(good[i] + "/ai-duanju/", { timeout: 5000, headers: hgHdr(good[i]) });
    var ms = Date.now() - t0;
    if (hgOk(rr) && ms < bestMs) { bestMs = ms; best = good[i]; }
  }
  hgClearBad();
  vars.set("line", best);
  try { cache.put("line.good", best, 900); } catch (e) {}
  try { ui.refreshExplore(); } catch (e) {}
  return "已切换：" + best.replace(/^https?:\/\//, "") + "（" + bestMs + "ms，可用 " + good.length + "/" + HG_LINES.length + "）";
}

function hgActReset() {
  hgClearBad();
  vars.set("line", HG_DEF);
  try { cache.put("line.good", HG_DEF, 900); } catch (e) {}
  try { ui.refreshExplore(); } catch (e) {}
  return "已恢复默认线路：" + HG_DEF.replace(/^https?:\/\//, "");
}

function hgActCur() {
  var v = vars.get("line");
  return "当前线路：" + (v ? String(v) : HG_DEF);
}

var HQ_KEY = 'UC2FmMyG928hRZY4';
var HQ_UA = 'Mozilla/5.0 (Linux; Android 12; V2283A) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
var HQ_B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
var HQ_TTL = 300;
var HQ_TIMEOUT = 9000;

function hqB64ToBytes(s) {
  var out = [], buf = 0, bits = 0, i, v, c;
  for (i = 0; i < s.length; i++) {
    c = s.charAt(i);
    if (c === '=') break;
    v = HQ_B64.indexOf(c);
    if (v < 0) continue;
    buf = (buf << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out.push((buf >> bits) & 255);
    }
  }
  return out;
}

function hqUtf8(bytes) {
  var out = '', i = 0, n = bytes.length, b, c, d, e, cp;
  while (i < n) {
    b = bytes[i++];
    if (b < 128) { out += String.fromCharCode(b); continue; }
    if (b >= 192 && b < 224 && i < n) {
      c = bytes[i++];
      out += String.fromCharCode(((b & 31) << 6) | (c & 63));
      continue;
    }
    if (b >= 224 && b < 240 && i + 1 < n) {
      c = bytes[i++]; d = bytes[i++];
      out += String.fromCharCode(((b & 15) << 12) | ((c & 63) << 6) | (d & 63));
      continue;
    }
    if (b >= 240 && i + 2 < n) {
      c = bytes[i++]; d = bytes[i++]; e = bytes[i++];
      cp = ((b & 7) << 18) | ((c & 63) << 12) | ((d & 63) << 6) | (e & 63);
      cp -= 65536;
      out += String.fromCharCode(55296 + (cp >> 10), 56320 + (cp & 1023));
      continue;
    }
    out += String.fromCharCode(65533);
  }
  return out;
}

function hqInv(html) {
  var s = String(html || '');
  var m = /APP\.Index\('([A-Za-z0-9_-]+)'\)/.exec(s);
  if (!m) return null;
  var t = m[1].replace(/-/g, '+').replace(/_/g, '/');
  var bytes = hqB64ToBytes(t);
  if (!bytes.length) return null;
  var i;
  for (i = 0; i < bytes.length; i++) bytes[i] = bytes[i] ^ HQ_KEY.charCodeAt(i % HQ_KEY.length);
  if (bytes[0] === 1) return { zip: 1 };
  var txt = hqUtf8(bytes.slice(1));
  try { return JSON.parse(txt); } catch (e) { return null; }
}

function hqGet(url, base) {
  var key = 'r:' + url;
  var hit = cache.get(key);
  if (hit) return String(hit);
  var r = http.get(url, {
    timeout: HQ_TIMEOUT,
    headers: { 'User-Agent': HQ_UA, 'Referer': String(base || url) + '/' }
  });
  if (!r.ok) throw new Error('请求失败 HTTP ' + r.status + '：' + url);
  var body = String(r.body || '');
  if (body) try { cache.put(key, body, HQ_TTL); } catch (e) {}
  return body;
}

function hqLoad(url, base) {
  var key = 'j:' + url;
  var hit = cache.get(key);
  if (hit) {
    try { return JSON.parse(String(hit)); } catch (e) {}
  }
  var d = hqInv(hqGet(url, base));
  if (d && !d.zip) {
    try { cache.put(key, JSON.stringify(d), HQ_TTL); } catch (e) {}
  }
  return d;
}

function hqBase(ctx) {
  var b = (ctx.vars && ctx.vars.server) ? String(ctx.vars.server) : String(ctx.source.url);
  return String(b).replace(/\/+$/, '');
}

function hqList(html, host) {
  var base = String(host || '').replace(/\/+$/, '');
