function hqDetail(ctx) {
  var base = hqBase(ctx);
  var u = String(ctx.book.bookUrl);
  if (u.indexOf('/videoplay/') >= 0) {
    var d = hqLoad(u, base);
    if (!d || !d.info) throw new Error('视频详情解析失败');
    var inf = d.info;
    var cls = (inf.vod_class || []).slice(0, 4).join(',');
    var kind = cls + (inf.vod_year ? (cls ? ',' : '') + inf.vod_year : '');
    return {
      name: inf.vod_name || '',
      coverUrl: inf.vod_pic || '',
      author: inf.user_name || '',
      intro: inf.vod_blurb || String(inf.vod_content || '').replace(/<[^>]+>/g, '').slice(0, 300),
      kind: kind,
      lastChapter: inf.vod_duration ? ('时长 ' + inf.vod_duration) : (inf.vod_remarks || ''),
      type: 'video'
    };
  }
  var body = hqGet(u, base);
  var name = '', kind = '', intro = '', cover = '', last = '';
  var p0 = /<p>\s*书(?:&nbsp;|\s)*名：([^<]*)<\/p>/.exec(body);
  if (p0) name = p0[1].replace(/&nbsp;/g, ' ').trim();
  if (!name) {
    var alt = /<div class="imgbox">[\s\S]{0,200}?alt="([^"]*)"/.exec(body);
    if (alt) name = alt[1];
  }
  var k1 = /类(?:&nbsp;|\s)*别：([^<]*)</.exec(body);
  if (k1) kind = k1[1].replace(/&nbsp;/g, '').trim();
  var k2 = /状(?:&nbsp;|\s)*态：([^<]*)</.exec(body);
  if (k2) kind = kind + (kind ? ',' : '') + k2[1].replace(/&nbsp;/g, '').trim();
  var d1 = /<div class="desc xs-hidden">([\s\S]*?)<\/div>/.exec(body);
  if (d1) intro = d1[1].replace(/<[^>]+>/g, '').trim();
  if (!intro) {
    var d2 = /<div class="m-desc xs-show">[\s\S]{0,80}?<\/strong>([\s\S]*?)<\/div>/.exec(body);
    if (d2) intro = d2[1].replace(/<[^>]+>/g, '').trim();
  }
  var c1 = /<div class="imgbox">[\s\S]{0,400}?(?:data-original|src)="([^"]+)"/.exec(body);
  if (c1) cover = c1[1];
  var l1 = /最新：[\s\S]{0,40}?<a[^>]*>([^<]*)<\/a>/.exec(body);
  if (l1) last = l1[1];
  var isComic = u.indexOf('/comic_ls/') >= 0 || String(ctx.book.type || '') === 'comic';
  return {
    name: name,
    coverUrl: cover,
    intro: intro.slice(0, 300),
    kind: kind,
    lastChapter: last,
    type: isComic ? 'comic' : 'text'
  };
}

function hqToc(ctx) {
  var base = hqBase(ctx);
  var u = String(ctx.book.bookUrl);
  var t = String(ctx.book.type || '');
  if (t === 'video' || u.indexOf('/videoplay/') >= 0) {
    var d = hqLoad(u, base);
    var nm = (d && d.info && d.info.vod_name) || ctx.book.name || '在线播放';
    return { list: [{ title: '▶ ' + nm, url: u }] };
  }
  var body = hqGet(u, base);
  var out = [];
  var m = /<ul[^>]*id="myList"[^>]*>([\s\S]*?)<\/ul>/.exec(body);
  var seg = m ? m[1] : '';
  var re = /<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
  var x, href, title;
  while ((x = re.exec(seg))) {
    href = x[1];
    title = x[2].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
    if (!href || href.indexOf('javascript') === 0) continue;
    if (href.charAt(0) === '/') href = base + href;
    out.push({ title: title || ('第' + (out.length + 1) + '话'), url: href });
  }
  if (!out.length) out.push({ title: '在线阅读', url: u });
  return { list: out };
}

function hqContent(ctx) {
  var base = hqBase(ctx);
  var u = String(ctx.chapter.url);
  var t = String(ctx.book.type || '');
  if (t === 'video' || u.indexOf('/videoplay/') >= 0) {
    var d = hqLoad(u, base);
    var inf = (d && d.info) || {};
    var v = inf.vod_play_url || '';
    if (!v) {
      return { text: '该视频暂无免费直链（可能需要金币/付费），可到原站观看：\n' + u };
    }
    return { video: v };
  }
  var body = hqGet(u, base);
  if (t === 'comic' || u.indexOf('/comic_details/') >= 0) {
    var imgs = [];
    var cm = /<ul[^>]*class="[^"]*cartoon[^"]*"[^>]*>([\s\S]*?)<\/ul>/.exec(body);
    var cseg = cm ? cm[1] : body;
    var ri = /<img[^>]*(?:data-original|src)="([^"]+)"/g;
    var y;
    while ((y = ri.exec(cseg))) {
      if (y[1].indexOf('data:') === 0) continue;
      imgs.push(y[1]);
    }
    if (!imgs.length) throw new Error('未取到漫画图片，页面结构可能变化');
    return { images: imgs };
  }
  var i = body.indexOf('id="art-content"');
  if (i < 0) throw new Error('未取到正文容器，请刷新本章');
  var seg = body.slice(i);
  var end = seg.indexOf('<div class="flex pagination');
  var html = seg.slice(seg.indexOf('>') + 1, end > 0 ? end : seg.length);
  html = html.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<ins[\s\S]*?<\/ins>/gi, '');
  if (!html || html.length < 20) throw new Error('正文为空或被截断，请刷新本章');
  html = html.replace(/<br\s*\/?>/gi, '\n').replace(/<\/(?:div|p|li|h[1-6])>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ') .replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return { text: html };
}

function hqSearch(ctx) {
  var base = hqBase(ctx);
  var k = encodeURIComponent(String(ctx.key || ''));
  var hdr = { 'User-Agent': HQ_UA, 'Referer': base + '/' };
  var rs = http.all([
    { url: base + '/so/video/' + k + '/1', headers: hdr, timeout: 8000 },
    { url: base + '/so/novel/' + k + '/1', headers: hdr, timeout: 8000 },
    { url: base + '/so/comic/' + k + '/1', headers: hdr, timeout: 8000 }
  ], { concurrency: 3, timeout: 8000, failOnPartial: false });
  var out = [];
  var r, parts, i, seg, mid, href, title, img;
  r = rs[0];
  if (r && r.ok) {
    parts = String(r.body).split('redirect_vod(');
    for (i = 1; i < parts.length; i++) {
      seg = parts[i].slice(0, 1500);
      mid = /^'(\d+)'/.exec(seg);
      if (!mid) continue;
      title = /videoGridH-item-title">([\s\S]*?)</.exec(seg);
      img = /<img[^>]*src="([^"]+)"/.exec(seg);
      out.push({
        name: title ? title[1].replace(/<[^>]+>/g, '').trim() : ('视频 ' + mid[1]),
        bookUrl: base + '/videoplay/' + mid[1],
