  }
  r = rs[1];
  if (r && r.ok) {
    parts = String(r.body).split('<div class="novel-grid-item">');
    for (i = 1; i < parts.length; i++) {
      seg = parts[i].slice(0, 1200);
      href = /href="(\/[a-z_]+_ls\/\d+)"/.exec(seg);
      if (!href || href[1].indexOf('/xs_ls/') < 0) continue;
      title = /novel-grid-item-title">([\s\S]*?)</.exec(seg);
      img = /<img[^>]*(?:data-original|src)="([^"]+)"/.exec(seg);
      out.push({
        name: title ? title[1].replace(/<[^>]+>/g, '').trim() : '',
        bookUrl: base + href[1],
        coverUrl: img ? img[1] : '',
        type: 'text'
      });
    }
  }
  r = rs[2];
  if (r && r.ok) {
    parts = String(r.body).split('<div class="novel-grid-item">');
    for (i = 1; i < parts.length; i++) {
      seg = parts[i].slice(0, 1200);
      href = /href="(\/[a-z_]+_ls\/\d+)"/.exec(seg);
      if (!href || href[1].indexOf('/comic_ls/') < 0) continue;
      title = /novel-grid-item-title">([\s\S]*?)</.exec(seg);
      img = /<img[^>]*(?:data-original|src)="([^"]+)"/.exec(seg);
      out.push({
        name: title ? title[1].replace(/<[^>]+>/g, '').trim() : '',
        bookUrl: base + href[1],
        coverUrl: img ? img[1] : '',
        type: 'comic'
      });
    }
  }
  return { list: out };
}

function hsckContent(ctx) {
  var url = ctx.chapter && ctx.chapter.url ? ctx.chapter.url : (ctx.book && ctx.book.bookUrl ? ctx.book.bookUrl : "");
  if (!url) throw new Error("缺少详情页地址");
  var cacheKey = "hsck:" + url;
  try { var cached = cache.get(cacheKey); if (cached) return cached; } catch (e) {}
  if (url.charAt(0) === "/") url = String(ctx.source.url).replace(/\/+$/, "") + url;
  var pageRes = http.get(url, { timeout: 9000 });
  if (!pageRes || !pageRes.ok || !pageRes.body) throw new Error("详情页请求失败：" + (pageRes ? (pageRes.error || pageRes.status) : "unknown"));
  var body = String(pageRes.body);
  var aid = (body.match(/var\s+AID=\x27([^\x27]+)\x27/) || [])[1] || "";
  var sid = (body.match(/var\s+ASID=\x27([^\x27]+)\x27/) || [])[1] || "";
  var nid = (body.match(/var\s+ANID=\x27([^\x27]+)\x27/) || [])[1] || "";
  var tk = (body.match(/var\s+AK=\x27([^\x27]+)\x27/) || [])[1] || "";
  if (!aid || !tk) throw new Error("详情页没有找到播放参数");
  var payload = "id=" + encodeURIComponent(aid) + "&sid=" + encodeURIComponent(sid) + "&nid=" + encodeURIComponent(nid) + "&tk=" + encodeURIComponent(tk) + "&g=1&x=1&y=1&dt=1&sw=390&sh=844&tz=-480&t=" + Date.now();
  var api = String(ctx.source.url).replace(/\/+$/, "") + "/static/count.php";
  var r = http.post(api, payload, { headers: { "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8", "X-Requested-With": "XMLHttpRequest", "Referer": url, "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Mobile/15E148 Safari/604.1" }, timeout: 9000 });
  if (!r || !r.ok || !r.body) throw new Error("播放接口请求失败：" + (r ? (r.error || r.status) : "unknown"));
  var data;
  try { data = JSON.parse(String(r.body)); } catch (e) { throw new Error("播放接口不是 JSON"); }
  if (!data || !data.ok || !data.u) throw new Error("播放接口没有返回地址：" + String(r.body).slice(0, 120));
  var video = native.unbase64(String(data.u));
  if (!video) throw new Error("播放地址解码为空");
  var out = { video: video, videoPage: url };
  try { cache.put(cacheKey, out, 300); } catch (e) {}
  return out;
}

// ===== 禁漫天堂（jmtt1 / 18mh 新版 jm-* 前端）轻页 v1 =====
// 结构：工具 -> 线路 -> 请求 -> 列表解析 -> 五阶段 -> 图片解密 -> 分支自检 -> 视频链
// 约束：QuickJS（无 DOM / cheerio / Node），只做字符串与正则；请求走 http.*
// 三模式不靠开关：URL 段 /comic/ /novel/ /mv/ 决定类型，每本书各自声明 type

// ---------- 工具 ----------
function unesc(s) {
  return String(s == null ? '' : s)
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&apos;/g, "'")
    .replace(/&ldquo;/g, '\u201c').replace(/&rdquo;/g, '\u201d')
    .replace(/&lsquo;/g, '\u2018').replace(/&rsquo;/g, '\u2019')
    .replace(/&hellip;/g, '\u2026').replace(/&mdash;/g, '\u2014').replace(/&ndash;/g, '\u2013')
    .replace(/&middot;/g, '\u00b7').replace(/&nbsp;/g, ' ').replace(/&ensp;/g, ' ')
    .replace(/&#x([0-9a-fA-F]+);/g, function (_, h) { return String.fromCharCode(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (_, n) { return String.fromCharCode(parseInt(n, 10)); });
}
function clean(s) {
  return unesc(String(s == null ? '' : s).replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
}
function nOf(v) {
