// ---------- 线路 ----------
// *.yyc2mhau.cc 任意单词子域同源（站点发布页词表随机取词），2026-11-01 实测多域直连可用
var HOSTS = [
  'https://abandon.yyc2mhau.cc',
  'https://ability.yyc2mhau.cc',
  'https://able.yyc2mhau.cc',
  'https://above.yyc2mhau.cc',
  'https://abroad.yyc2mhau.cc',
  'https://absence.yyc2mhau.cc'
