}

// ---------- 列表解析 ----------
// 真封面都在 /upload_01/upload/ 或 /upload_01/ads/；/hc237/、/static/、/upload-images/ 是广告
function isCover(u) {
  var s = String(u || '');
  if (!/^https?:\/\//i.test(s)) return false;
  if (/\/hc237\//i.test(s) || /\/upload-images\//i.test(s) || /\/(static|templates)\//i.test(s)) return false;
  return /\/upload(_\d+)?\/(upload|ads)\//i.test(s);
}
