  var wi = h.indexOf('data-jm-feed-wall');
  if (wi >= 0) {
    var end = h.indexOf('class="pager', wi);
    if (end < 0) end = h.length;
    wall = h.slice(wi, end);
  }
  var out = [], seen = {}, re = /<li class="jm-(?:card|vcard)[^"]*"[^>]*>[\s\S]*?<\/li>/g, m;
  while ((m = re.exec(wall)) !== null) {
    var segHtml = m[0];
    var lm = segHtml.match(/href="(\/comic\/detail\/\d+|\/novel\/detail\/\d+|\/mv\/detail\/\d+)"/);
    if (!lm) continue;
    var url = lm[1];
    var key = url.split('/').pop();
    if (seen[key]) continue;
    seen[key] = 1;
    var name = '';
    var nm = segHtml.match(/class="jm-(?:card|vcard)__link"[^>]*>([\s\S]*?)<\/a>/);
    if (nm) name = clean(nm[1]);
    if (!name) { var im = segHtml.match(/alt="([^"]{1,200})"/); if (im) name = clean(im[1]); }
    if (!name) continue;
    var cover = firstSrc(segHtml);
    if (cover && !isCover(cover)) cover = '';
    // 分类/标签
