  return String(u || '').replace(/#.*$/, '').replace(/\/\d+\/?$/, '').replace(/\/+$/, '');
}

// ---------- 搜索 ----------
// 站内按整词命中；第 1 页 /x/all?key_word=，第 2 页起 /x/all/page/N?key_word=
// （漫画搜索只有 1 页：pager data-rec-total=7 / per-page=20，page/2 固定 404）
function stageSearch(ctx) {
  var kw = String((ctx && ctx.key) || '').replace(/^\s+|\s+$/g, '');
  if (!kw) throw new Error('搜索词为空');
  var pg = nOf(ctx && ctx.page);
  var host = hostOf();
  var enc = encodeURIComponent(kw);
  var segs = ['comic', 'novel', 'mv'];
  var out = [];
  for (var i = 0; i < segs.length; i++) {
    var seg = segs[i];
    // 结果不足一页时站点对第 2 页回 404；先用第 1 页 pager 的总数预算页数
    var ck = 'jmS:' + seg + ':' + kw;
    var maxPg = memoNum(ck);
    if (pg > 1 && maxPg > 0 && pg > maxPg) continue;
    var body = null;
    try {
      var path = pg > 1
        ? '/' + seg + '/all/page/' + pg + '?key_word=' + enc
        : '/' + seg + '/all?key_word=' + enc;
      body = jmGet(path, '搜索');
    } catch (e) {
      // 越界页（该关键词结果不足一页）站点回 404，按"没有更多"处理
      if (pg > 1 && /HTTP 404/.test(String((e && e.message) || ''))) continue;
      if (i === 0) throw e;
      continue;
    }
    if (pg === 1) memoSave(ck, maxPageOf(body));
