  if (!cid) throw new Error('详情阶段拿不到作品 id：' + bookUrl);
  var html = jmGet('/' + seg + '/detail/' + cid, '详情');

  var name = '';
  var tm = html.match(/<h1 class="jm-dt-title"[^>]*>([\s\S]{0,300}?)<\/h1>/);
  if (tm) name = clean(tm[1]);
  if (!name) { var om2 = html.match(/property="og:title"\s+content="([^"]{1,200})"/); if (om2) name = clean(om2[1]).split('|')[0]; }
