  }

  var cid = (bookUrl.match(/\/(?:comic|novel)\/detail\/(\d+)/) || [])[1];
  if (!cid) throw new Error('目录阶段拿不到作品 id：' + bookUrl);
  var html = jmGet('/' + seg + '/detail/' + cid, '目录');

  var out = [], seen = {};
  if (seg === 'comic') {
    // 不分页，DOM 即正序（第1话在最前）
    var re = /<a class="jm-dt-ch[^"]*" href="\/comic\/chapter\/(\d+)\/(\d+)"[^>]*>([\s\S]*?)<\/a>/g, m;
    while ((m = re.exec(html)) !== null) {
      var href = '/comic/chapter/' + m[1] + '/' + m[2];
      if (seen[href]) continue;
      seen[href] = 1;
      var segHtml = m[3];
      var noText = '';
      var n1 = segHtml.match(/class="jm-dt-ch__no"[^>]*>([\s\S]{0,40}?)<\/span>/);
