      var t1 = segHtml.match(/class="jm-dt-ch__t"[^>]*>([\s\S]{0,300}?)<\/span>/);
      if (t1) title = clean(t1[1]);
      if (!title) title = noText || ('第' + m[2] + '话');
      else if (noText) {
        var flatNo = noText.replace(/\s+/g, ''), flatT = title.replace(/\s+/g, '');
        if (flatT !== flatNo && flatT.indexOf(flatNo) < 0) title = noText + ' ' + title;
      }
      var date = '';
      var d1 = segHtml.match(/class="jm-dt-ch__d"[^>]*>([\s\S]{0,300}?)<\/span>/);
      if (d1) date = clean(d1[1].replace(/<svg[\s\S]*?<\/svg>/g, ' '));
      out.push({ title: title, url: host + href, tag: date });
    }
  } else {
    // 小说：a.jm-dt-ch href=/novel_chapter/{id}/{no}.html（约 180 章一页全量）
    var re2 = /<a class="jm-dt-ch[^"]*" href="(\/novel_chapter\/\d+\/(\d+)\.html)"[^>]*>([\s\S]*?)<\/a>/g, m2;
    while ((m2 = re2.exec(html)) !== null) {
      var href2 = m2[1];
      if (seen[href2]) continue;
      seen[href2] = 1;
      var segHtml2 = m2[3];
      var noText2 = '';
      var n2 = segHtml2.match(/class="jm-dt-ch__no"[^>]*>([\s\S]{0,40}?)<\/span>/);
      if (n2) noText2 = clean(n2[1]);
      var title2 = '';
      var t2 = segHtml2.match(/class="jm-dt-ch__t"[^>]*>([\s\S]{0,300}?)<\/span>/);
      if (t2) title2 = clean(t2[1]);
      if (!title2) title2 = noText2 || ('第' + m2[2] + '章');
      else if (noText2) {
        var fNo = noText2.replace(/\s+/g, ''), fT = title2.replace(/\s+/g, '');
        if (fT !== fNo && fT.indexOf(fNo) < 0) title2 = noText2 + ' ' + title2;
      }
      var date2 = '';
      var d2 = segHtml2.match(/class="jm-dt-ch__d"[^>]*>([\s\S]{0,300}?)<\/span>/);
      if (d2) date2 = clean(d2[1].replace(/<svg[\s\S]*?<\/svg>/g, ' '));
      out.push({ title: title2, url: host + href2, tag: date2 });
    }
  }
  if (!out.length) throw new Error('目录为空：站点结构可能已改版（找不到 a.jm-dt-ch）');
  return out;
}

