function extractImages(html) {
  var h = String(html || '');
  var box = h;
  var si = h.indexOf('<section class="jm-rd-pages"');
  if (si < 0) si = h.indexOf('class="jm-rd-pages"');
  if (si >= 0) {
    var se = h.indexOf('</section>', si);
    box = se > si ? h.slice(si, se) : h.slice(si, si + 300000);
  }
  var out = [], seen = {}, re = /<img\b[^>]*>/g, m;
  while ((m = re.exec(box)) !== null) {
    var tag = m[0];
    // 带 class 的（jm-mtab__img / jm-iconads / logo）都是 UI 或广告
    if (/\sclass="/.test(tag)) continue;
    var a1 = tag.match(/data-src="([^"]+)"/);
    var a2 = tag.match(/\ssrc="(https?:\/\/[^"]+)"/);
    var u = unesc(a1 ? a1[1] : (a2 ? a2[1] : ''));
    if (!u || !/^https?:\/\//i.test(u)) continue;
    if (!/\.(jpe?g|png|webp|gif)(\?|&|#|$)/i.test(u)) continue;
    if (/\/static\//i.test(u) || /logo\.png/i.test(u)) continue;
    if (seen[u]) continue;
    seen[u] = 1;
    out.push(u);
  }
  return out;
}

// 图片解密：站内图整体 AES-128-CBC 加密；少数已是明文（广告位/旧 CDN），先验魔数
function isImageBytes(b) {
  if (!b || b.length < 4) return false;
  var b0 = b[0], b1 = b[1], b2 = b[2], b3 = b[3];
  if (b0 === 0xFF && b1 === 0xD8) return true;
  if (b0 === 0x89 && b1 === 0x50 && b2 === 0x4E && b3 === 0x47) return true;
  if (b0 === 0x47 && b1 === 0x49 && b2 === 0x46) return true;
  if (b0 === 0x52 && b1 === 0x49 && b2 === 0x46 && b3 === 0x46) return true;
  return false;
}
var IMG_KEY = '66356439363564663735333336323730';
var IMG_IV = '39376236303339346162633266626531';
function decodeImage(bytes, ctx) {
  if (!bytes || !bytes.length) return bytes;
  if (isImageBytes(bytes)) return bytes;
  var out = null;
  try { out = image.decrypt('AES/CBC/PKCS7Padding', bytes, IMG_KEY, IMG_IV); } catch (e) { out = null; }
  if (out && isImageBytes(out)) return out;
  var n = bytes.length - (bytes.length % 16);
  if (!n) return bytes;
  var raw = null;
  try { raw = image.decrypt('AES/CBC/NoPadding', bytes.subarray(0, n), IMG_KEY, IMG_IV); } catch (e) { raw = null; }
  if (!raw) return bytes;
  // JPEG 尾巴切 FFD9
  var end = -1;
  for (var k = raw.length - 2; k >= 0 && k > raw.length - 128; k--) {
    if (raw[k] === 0xFF && raw[k + 1] === 0xD9) { end = k + 2; break; }
  }
  if (end > 0) return raw.subarray(0, end);
  return raw;
}

// ---------- 视频链 ----------
// /mv/detail/{id} -> /mv/embed?id={id}（packer 混淆）-> /videos/detail_embed.js?img=&u=&t=（再一层 packer）-> /media/m3u8?...
// 静态解两层 packer 即可拿到播放地址，交给内置播放器；videoPage 留原站网页做回退
function unpackPacker(src) {
  var s = String(src || '');
  var m = s.match(/eval\(function\(p,a,c,k,e,d\)\{[\s\S]*?\}\('([\s\S]*?)',(\d+),(\d+),'([\s\S]*?)'\.split\('\|'\)/);
  if (!m) return '';
  var payload = m[1], a = parseInt(m[2], 10), c = parseInt(m[3], 10);
  var k = m[4].split('|');
  function enc(x) { return (x < a ? '' : enc(parseInt(x / a, 10))) + ((x = x % a) > 35 ? String.fromCharCode(x + 29) : x.toString(36)); }
  var out = payload;
  for (var i = c - 1; i >= 0; i--) {
    if (!k[i]) continue;
    out = out.replace(new RegExp('\\b' + enc(i) + '\\b', 'g'), k[i]);
  }
  return out;
}

function videoContent(mid) {
  var host = hostOf();
  var embedUrl = host + '/mv/embed?id=' + mid;
  var body = jmGet(embedUrl, '视频页');
  var js1 = unpackPacker(body);
  if (!js1) throw new Error('视频页解析失败（找不到播放脚本）');

  var imgM = js1.match(/img=([^&"\\]+)/);
  var uM = js1.match(/\+\s*encodeURIComponent\("([^"]+)"\)/);
  var videoUrl = '';
  if (imgM && uM) {
    var t = Math.floor(Date.now() / 1000 / 1800);
    var playUrl = host + '/videos/detail_embed.js?img=' + imgM[1] + '&u=' + encodeURIComponent(uM[1]) + '&t=' + t;
    var r = null;
    try { r = http.get(playUrl, { headers: hdr() }); } catch (e) { r = null; }
    if (r && r.ok && r.status === 200) {
      var js2 = unpackPacker(String(r.body || ''));
      var m3 = js2.match(/src="(\/media\/m3u8\?[^"]+)"/);
      if (m3) videoUrl = host + unesc(m3[1]);
    }
  }
  return {
    video: videoUrl,
    videoPage: embedUrl,
    mediaError: videoUrl ? '' : '直链没解出来，可用「网页播放」'
  };
}

