// ---------- 从发布页刷新线路 ----------
// jmtt1.net 只放导航不挂内容：首页 words='...' 是 *.yyc2mhau.cc 的词表（2026-11-05 实测 306 词）
function actFetchLines() {
  var out = ['发布页刷新线路'];
  var text = '';
  try {
    var r = http.get('https://jmtt1.net/', { headers: hdr() });
    if (!r || !r.ok || r.status !== 200) throw new Error('HTTP ' + (r && r.status));
    text = String(r.body || '');
  } catch (e) {
    return out.join('\n') + '\n\u2717 发布页不可达：' + String((e && e.message) || e).split('\n')[0];
  }
  var m = text.match(/words\s*=\s*'([a-z,]+)'/);
  if (!m) return out.join('\n') + '\n\u2717 发布页没有线路词表（结构可能已变）';
  var words = m[1].split(',');
  out.push('词表 ' + words.length + ' 词');
  var cand = [], seen = {}, max = 8;
  for (var i = 0; i < max; i++) {
    var w = words[Math.floor(i * words.length / max)];
    if (!w || seen[w]) continue;
    seen[w] = 1;
    cand.push('https://' + w + '.yyc2mhau.cc');
  }
  var ok = [], best = '', bestMs = 1e9;
  for (var j = 0; j < cand.length; j++) {
    var h = cand[j], t0 = Date.now(), good = false, ms = 0, note = '';
    try {
      var resp = http.get(h + '/comic/all', { headers: hdr() });
      ms = Date.now() - t0;
      good = !!(resp && resp.ok && resp.status === 200 && /jm-card/.test(String(resp.body || '')));
      note = good ? ms + 'ms' : ('HTTP ' + (resp && resp.status));
    } catch (e) { ms = Date.now() - t0; note = '异常'; }
    out.push((good ? '\u2713 ' : '\u2717 ') + h.replace(/^https?:\/\//, '') + '  ' + note);
    if (good) {
      ok.push(h);
      if (ms < bestMs) { bestMs = ms; best = h; }
    }
  }
  if (!best) return out.join('\n') + '\n\u2717 抽样线路全部不通，保留原线路：' + hostOf();
  HOSTS.length = 0;
  for (var k = 0; k < ok.length; k++) HOSTS.push(ok[k]);
  try { vars.set('host', best); } catch (e) {}
  out.push('\n\u2713 已切换：' + best.replace(/^https?:\/\//, '') + '（' + bestMs + 'ms，可用 ' + ok.length + ' 条）');
  return out.join('\n');
}

