var ROUM_B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function roumUnescape(value) {
  return String(value == null ? '' : value)
    .replace(/\\+u002[fF]/g, '/')
    .replace(/\\+u0026/g, '&')
    .replace(/\\+\//g, '/')
    .replace(/\\+"/g, '"')
    .replace(/&quot;/gi, '"')
    .replace(/&#x2[fF];/g, '/')
    .replace(/&#0*47;/g, '/')
    .replace(/&amp;/gi, '&');
}

function roumBase64(value) {
  var text = String(value == null ? '' : value).replace(/-/g, '+').replace(/_/g, '/').replace(/[^A-Za-z0-9+/=]/g, '');
  if (!text) return new Uint8Array(0);
  if (text.length % 4 !== 0) text += '===='.slice(text.length % 4);
  var out = [];
  for (var i = 0; i < text.length; i += 4) {
    var c1 = ROUM_B64.indexOf(text.charAt(i));
    var c2 = ROUM_B64.indexOf(text.charAt(i + 1));
    var c3 = i + 2 < text.length ? ROUM_B64.indexOf(text.charAt(i + 2)) : -1;
    var c4 = i + 3 < text.length ? ROUM_B64.indexOf(text.charAt(i + 3)) : -1;
    if (c1 < 0 || c2 < 0) break;
    out.push((c1 << 2) | (c2 >> 4));
    if (c3 >= 0) out.push(((c2 & 15) << 4) | (c3 >> 2));
    if (c4 >= 0) out.push(((c3 & 3) << 6) | c4);
  }
  return new Uint8Array(out);
}

function roumImagePath(url) {
  var clean = String(url == null ? '' : url).split('?')[0].split('#')[0];
  var segment = clean.substring(clean.lastIndexOf('/') + 1);
  segment = segment.replace(/\.(?:jpe?g|png|webp|gif|avif)$/i, '');
  segment = segment.replace(/%3D/gi, '=').replace(/%2B/gi, '+').replace(/%2F/gi, '/');
  var bytes = roumBase64(segment);
  if (!bytes.length) return '';
  var text = '';
  for (var i = 0; i < bytes.length; i++) text += String.fromCharCode(bytes[i]);
  return text;
}

function roumPushImage(out, seen, value) {
  var url = roumUnescape(value).trim();
  if (!url || /\/loading\.jpg(?:$|[?#])/i.test(url)) return;
  if (url.indexOf('//') === 0) url = 'https:' + url;
  if (!/^https?:\/\//i.test(url)) return;
  var path = roumImagePath(url);
  if (path) {
    if (/^s3:\/\/roupub\//i.test(path) || /\/adcs\//i.test(path) || /\/advertiser-assets\//i.test(path)) return;
    if (/\/cover\.(?:jpe?g|png|webp|gif|avif)$/i.test(path)) return;
  }
  if (seen[url]) return;
  seen[url] = 1;
  out.push(url);
}

function roumArrayEnd(text, start) {
  var depth = 0;
  var inString = false;
  var escape = false;
  for (var i = start; i < text.length; i++) {
    var ch = text.charAt(i);
    if (inString) {
      if (escape) escape = false;
      else if (ch === '\\') escape = true;
      else if (ch === '"') inString = false;
    } else if (ch === '"') {
      inString = true;
    } else if (ch === '[') {
      depth++;
    } else if (ch === ']') {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

