function roumImageDecode(input, ctx) {
  var url = ctx && ctx.url ? String(ctx.url) : '';
  if (url.indexOf('sr:1') < 0) return input;
  var segment = url.split('?')[0].split('#')[0];
  segment = segment.substring(segment.lastIndexOf('/') + 1);
  segment = segment.replace(/\.(?:jpe?g|png|webp|gif|avif)$/i, '');
  segment = segment.replace(/%3D/gi, '=').replace(/%2B/gi, '+').replace(/%2F/gi, '/');
  var decoded = roumBase64(segment);
  if (!decoded.length) return input;
  var digest = image.hash('md5', decoded);
  var count = (digest[digest.length - 1] % 10) + 5;
  var format = 'image/jpeg';
  if (input.length > 11 && input[0] === 0x89 && input[1] === 0x50 && input[2] === 0x4E && input[3] === 0x47) {
    format = 'image/png';
  } else if (input.length > 11 && input[0] === 0x52 && input[1] === 0x49 && input[2] === 0x46 &&
    input[3] === 0x46 && input[8] === 0x57 && input[9] === 0x45 && input[10] === 0x42 && input[11] === 0x50) {
    format = 'image/webp';
  }
  var order = [];
  for (var i = 0; i < count; i++) order.push(count - 1 - i);
  return image.reorderStrips(input, { count: count, order: order, remainder: 'last', format: format, quality: 95 });
}

