function actChapterBench() {
  var host = hostOf();
  var t0 = Date.now();
  var html = "";
  var pageMs = 0, parseMs = 0, dlMs = 0, decMs = 0, err = "";
  try {
    html = aGet("/comic/chapter/101/1", "\u6d4b\u901f\u9875");
    pageMs = Date.now() - t0;
  } catch (e) { err = String(e.message || e).slice(0, 120); }
  if (!html) { ui.toast("\u9875\u9762\u8bf7\u6c42\u5931\u8d25\uff1a" + err); return; }
  var t1 = Date.now();
  var imgs = [], seen = {}, re = /<img\b[^>]*>/g, mm;
  while ((mm = re.exec(html)) !== null) {
    var a1 = mm[0].match(/data-src="([^"]+)"/);
    var a2 = mm[0].match(/data-original="([^"]+)"/);
    var a3 = mm[0].match(/\ssrc="(https?:\/\/[^"]+)"/);
    var u = unesc(a1 ? a1[1] : (a2 ? a2[1] : (a3 ? a3[1] : "")));
    if (!u || !aIsImage(u)) continue;
    u = u.replace(/&amp;/g, "&");
    if (seen[u]) continue;
    seen[u] = 1; imgs.push(u);
  }
  parseMs = Date.now() - t1;
  // 单张下载
  var s1 = Date.now();
  var r = http.get(imgs[0], { headers: { "Referer": host + "/", "User-Agent": "Mozilla/5.0" } });
  var dl = Date.now() - s1;
  var dec = 0, size = 0;
  if (r && r.ok) {
    var raw = bytesOfText(String(r.body || ""));
    size = raw.length;
    var s2 = Date.now();
    try { decodeImage(raw, { index: 0, params: {} }); } catch (e2) {}
    dec = Date.now() - s2;
  }
  ui.toast("\u7ae0\u8282\u9875 " + pageMs + "ms | \u89e3\u6790 " + parseMs + "ms " + imgs.length +
    "\u5f20 | \u9996\u56fe\u4e0b\u8f7d " + dl + "ms | \u89e3\u5bc6 " + dec + "ms | " + size + "B\n" +
    "\u5168\u7ae0\u6309\u4e32\u884c\u4f30\u7b97\uff1a" + Math.round((dl + dec) * imgs.length / 1000) + "s");
  return "";
}

