function qbDay(ts) {
  var n = Number(ts);
  if (!n || n !== n) return '';
  var d = new Date(n * 1000);
  var mm = d.getMonth() + 1;
  var dd = d.getDate();
  return d.getFullYear() + '-' + (mm < 10 ? '0' + mm : mm) + '-' + (dd < 10 ? '0' + dd : dd);
}

function qbParse(res) {
  if (!res || !res.ok) throw new Error('榜单请求失败：HTTP ' + (res ? res.status : '?') + (res && res.error ? ' ' + res.error : ''));
  var payload = null;
  try { payload = res.json(); } catch (e) { throw new Error('榜单接口返回的不是 JSON'); }
  if (payload && payload.ret !== undefined && payload.ret !== 0) {
    throw new Error('榜单接口返回 ' + payload.ret + '：' + (payload.msg || ''));
  }
  return (payload && Array.isArray(payload.rows)) ? payload.rows : [];
}

function exploreBooks(ctx) {
  var base = String(ctx.url || '');
  if (!base) throw new Error('这个分类没有可用的地址');
  var page = Number(ctx.page) || 1;
  var cacheKey = 'qb:explore:' + base + ':' + page;
  try { var cached = cache.get(cacheKey); if (cached) return cached; } catch (e) {}
  var from = (page - 1) * 3;
  var to = Math.min(from + 3, QB_WINDOWS.length);
  if (from >= QB_WINDOWS.length) return [];
  var urls = [];
  for (var k = from; k < to; k++) urls.push(base + QB_WINDOWS[k]);
  var pages = http.all(urls);
  var rows = [];
  var seen = {};
  var empty = 0;
  for (var p = 0; p < pages.length; p++) {
    var part = qbParse(pages[p]);
    if (part.length === 0) continue;
    for (var i = 0; i < part.length; i++) {
      var r = part[i] || {};
      var id = String(r.resourceID || '');
      if (!id || !r.resourceName || seen[id]) continue;
      seen[id] = 1;
      rows.push(r);
    }
  }
  log('第', page, '页', from + 1, '-', to, '段，取到', rows.length, '本');
  if (rows.length === 0) return [];
  var books = [];
  for (var j = 0; j < rows.length; j++) {
    var b = rows[j];
    var size = Number(b.contentsize);
    var wan = (size === size && size > 0) ? Math.round(size / 1000) / 10 : 0;
    var done = (b.isfinish === true || b.isfinish === 1 || b.isfinish === '1');
    var score = (b.userscore === undefined || b.userscore === null) ? '' : b.userscore;
    books.push({
      name: String(b.resourceName).replace(/（.*/, '').trim(),
      author: b.author ? String(b.author) : '',
      bookUrl: 'https://bookshelf.html5.qq.com/qbread/api/novel/intro-info?bookid=' + b.resourceID,
      coverUrl: b.picurl ? String(b.picurl) : '',
      intro: b.summary ? String(b.summary) : '',
      kind: wan + '万字 ' + score + '分 ' + (b.subject || '') + ' ' + (done ? '已完结' : '连载中'),
      wordCount: wan + '万字',
      status: done ? '已完结' : '连载中',
      updateTime: qbDay(b.lastUpdatetime)
    });
  }
  try { cache.put(cacheKey, books, 300); } catch (e) {}
  return books;
}

function mmUnescape(u) {
  var bs = String.fromCharCode(92);
  return String(u).split(bs + '/').join('/').split(bs + 'u0026').join('&').split('&amp;').join('&');
}
function mmPlay(ctx) {
  var cacheKey = 'mm:play:' + String(ctx.chapter.url);
  try { var cached = cache.get(cacheKey); if (cached) return cached; } catch (e) {}
  var r = http.get(ctx.chapter.url, { timeout: 9000 });
  if (!r.ok) throw new Error('播放页失败：' + (r.error || r.status));
  var h = r.body;
  var i = h.indexOf('player_aaaa');
  if (i >= 0) {
    var seg = h.slice(i, i + 4000);
    var m = /"url":"([^"]+)"/.exec(seg);
    if (m && m[1]) { var out = { video: mmUnescape(m[1]) }; try { cache.put(cacheKey, out, 300); } catch (e) {} return out; }
