fn clean(html) {
  let t = stripHtml(html)
  let out = []
  for line in split(t, '\n') {
    let s = trim(line)
    s = trim(replace(s, '[(]第[0-9]+/[0-9]+页[)]', ''))
    if (s != '' && !contains(s, '最新网址') && !contains(s, '本章未完') && !startsWith(s, 'id="nr1"')) { push(out, s) }
  }
  return join(out, '\n')
}
fn nextPage(url, href) {
  if (href == '') { return '' }
  let h = absUrl(href, url)
  let base = test(url, '_[0-9]+_[0-9]+\\.html$') ? replace(url, '_[0-9]+\\.html$', '') : replace(url, '\\.html$', '')
  return startsWith(h, base + '_') ? h : ''
}

