}

function metaContent(html, names) {
  var tags = String(html || "").match(/<meta\b[^>]*>/gi) || [];
  for (var i = 0; i < tags.length; i++) {
    var key = /(?:name|property)\s*=\s*["']([^"']+)["']/i.exec(tags[i]);
    if (!key || names.indexOf(key[1].toLowerCase()) < 0) continue;
    var c = /content\s*=\s*["']([^"']*)["']/i.exec(tags[i]);
    if (c && c[1]) return unesc(c[1]).trim();
  }
