}

function stageSearch(ctx) {
  ensureBase(false);
  var kw = String((ctx && ctx.key) || "").replace(/^\s+|\s+$/g, "");
  if (!kw) throw new Error("搜索词为空");
  var pg = nOf(ctx && ctx.page);
  var url = host() + "/search/?q=" + encodeURIComponent(kw) + (pg > 1 ? "&page=" + pg : "");
  var html = fetchPage(url, "搜索");
  var rows = parseCards(html);
  return rows.length ? rows : parseFallback(html);
}

function stageExplore(ctx) {
  ensureBase(false);
  var base = String((ctx && (ctx.url || (ctx.menu && ctx.menu.url))) || "/rank/new/");
  var pg = nOf(ctx && ctx.page);
  var url = /^https?:/i.test(base) ? base : host() + (base.charAt(0) === "/" ? base : "/" + base);
  // 分类/标签/榜单的翻页都是 /xxx/N.html
  if (pg > 1) url = url.replace(/[?#].*$/, "").replace(/\/+$/, "") + "/" + pg + ".html";
  var html = fetchPage(url, "分类");
  var rows = parseCards(html);
  return rows.length ? rows : parseFallback(html);
}

function stageDetail(ctx) {
  ensureBase(false);
  var bookUrl = String((ctx && ctx.book && (ctx.book.bookUrl || ctx.book.tocUrl)) || "");
  var pm = /\/(novel|freebook)\/(\d+)/i.exec(bookUrl);
  if (!pm) throw new Error("详情阶段拿不到书籍地址：" + bookUrl);
  var kind = pm[1].toLowerCase(), bid = pm[2];
  var bookHref = host() + "/" + kind + "/" + bid + "/";
  var html = fetchPage(bookHref, "详情");
  try { cache.put("yqks:detail:" + bid, html, 300); } catch (e) {}

  var name = "";
  var tm = /<h1[^>]*>([\s\S]{0,240}?)<\/h1>/i.exec(html);
  if (tm) name = strip(tm[1]).split("\n")[0].replace(/\s+/g, " ").trim();
  if (!name) {
    name = metaContent(html, ["og:title", "title"]).split(/[_|｜]/)[0].replace(/\s*-\s*一起看书\s*$/, "").trim();
  }
  if (!name) throw new Error("详情页解析不到书名，站点结构可能已改版：" + bookUrl);

  var author = "";
  var am = /作者\s*[：:]\s*(?:<[^>]*>\s*)*([^<\n]{1,40})/i.exec(html);
  if (am) author = strip(am[1]).trim();
  if (!author) {
    var am2 = /作者\s*[：:][\s\S]{0,60}?<a[^>]*>([^<]{1,40})<\/a>/i.exec(html);
    if (am2) author = strip(am2[1]).trim();
  }

  var status = "";
  var sm = /状态\s*[：:]\s*(?:<[^>]*>\s*)*([^<\n]{1,12})/i.exec(html);
  if (sm) status = strip(sm[1]).trim();

  // 分类在 /category/ 下，标签在 /tag/ 下，合并成 kind
  var kinds = [], kre = /href=["'][^"']*\/(?:category|freetag|tag)\/\d+\/?(?:[?#][^"']*)?["'][^>]*>([^<]{1,16})</gi, km;
  while ((km = kre.exec(html)) !== null) {
    var k = strip(km[1]).trim();
    if (k && kinds.indexOf(k) < 0 && kinds.length < 8) kinds.push(k);
  }

  // 简介优先取详情里的 desc 段落；meta description 是站点 SEO 文案，只作兜底
  var intro = "";
  var dm = /<div[^>]*class=["'][^"']*\bdesc\b[^"']*["'][^>]*>([\s\S]{10,4000}?)<\/div>/i.exec(html);
  if (dm) intro = strip(dm[1]);
  if (!intro) {
    intro = metaContent(html, ["og:description", "description"])
