  var re = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi, m, out = [], seen = {};
  while ((m = re.exec(body)) !== null) {
    var hm = /href\s*=\s*["']([^"']+)["']/i.exec(m[1] || "");
