function junkLine(line, bookName) {
  if (bookName && line === bookName) return true;
  if (/^(作者|状态|分类|标签|最新|最新章节|字数|点击|收藏|推荐|开始阅读|加入书架|上一章|下一章|返回目录|目录)\s*[：:]?/.test(line) && line.length < 24) return true;
  if (/^(已完结|连载中|连载|完结)(\s|$)/.test(line) && line.length < 16) return true;
  if (/^(免费|VIP)$/i.test(line)) return true;
  if (/一起看书|最新网址|本站|请记住|最新章节|广告|APP下载|app下载|章节错误|点此举报|加入书签|手机阅读|手机版|电脑版|扫码|本章未完|点击下一页/.test(line) && line.length < 50) return true;
  return false;
}

function extractText(html, bookName) {
  var text = String(html || "");
  var hm = /<h1\b[^>]*>[\s\S]{0,300}?<\/h1>/i.exec(text);
  if (hm) text = text.slice(hm.index + hm[0].length);
  // 取最后一次出现的「上一章」：页首若也有翻页条，用第一次会把正文切掉
  var nav = -1, nm;
  var nre = />\s*上一章\s*</g;
  while ((nm = nre.exec(text)) !== null) nav = nm.index;
  if (nav < 0) {
    nre = /上一章/g;
    while ((nm = nre.exec(text)) !== null) nav = nm.index;
  }
  if (nav > 0) text = text.slice(0, nav);
  text = text.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ");

  // 正文容器 class="content"；从这里开始，页头的封面/书名/标签面板就全被切掉了
  var c = text.indexOf('class="content"');
  if (c < 0) c = text.indexOf("class='content'");
  if (c >= 0) {
    var gt = text.indexOf(">", c);
    if (gt > 0) text = text.slice(gt + 1);
  } else {
    // 兜底：页头面板以标签链接结尾，正文里不会出现 /tag/<id>/
    var lastTag = -1, tre = /\/tag\/\d+\//g, tm2;
    while ((tm2 = tre.exec(text)) !== null) lastTag = tm2.index;
    if (lastTag > 0) {
      var closeTag = text.indexOf("</a>", lastTag);
      if (closeTag > 0 && text.length - closeTag > 120) text = text.slice(closeTag + 4);
    }
  }

  var paras = [], re = /<p\b[^>]*>([\s\S]*?)<\/p>/gi, pm;
  while ((pm = re.exec(text)) !== null) {
    var p = strip(pm[1]);
    if (p) paras.push(p);
  }
  var body = paras.join("\n");
  if (body.replace(/\s/g, "").length < 80) body = strip(text.replace(/<br\s*\/?>/gi, "\n"));

  var lines = body.split(/\n+/), keep = [];
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].replace(/[\u200b\ufeff]/g, "").replace(/\s+/g, " ").trim();
    if (!line) continue;
    if (junkLine(line, bookName)) continue;
    keep.push(line);
  }
  // 开头若残留状态/标签等短行，继续跳过
  while (keep.length && keep[0].length < 10 && !/[。！？…”』」）]/.test(keep[0])) keep.shift();
  return keep.join("\n");
}

