function omoResponse(url,tries,timeout){var r=null;for(var i=0;i<tries;i++){r=http.get(url,{timeout:timeout,headers:omoHeaders()});if(r&&r.ok&&r.body){return r;}if(i<tries-1){sleep(600);}}return r;}
function omoPass(base){try{var h=omoResponse(base+'/',3,9000);if(!h||!h.ok){return false;}var hd=omoHeaders();hd['Content-Type']='application/x-www-form-urlencoded';hd['X-Requested-With']='XML'+'HttpRequest';hd['Referer']=base+'/';var r=http.post(base+'/index.php/ajax/verify_check?type=search','i='+encodeURIComponent(omoToken()),{timeout:9000,headers:hd});return r.ok&&String(r.body||'').indexOf('\"code\":1')>=0;}catch(e){return false;}}
function omoGet(url,base){var k='omo:html:'+String(url||'');var hit=cache.get(k);if(hit){return String(hit);}var body=omoFetch(url,base);if(body){try{cache.put(k,body,300);}catch(e){}}return body;}
function omoFetch(url,base){var last=null;for(var i=0;i<4;i++){var r=omoResponse(url,2,9000);last=r;if(r&&r.ok&&r.body){var b=String(r.body);if(!omoShield(b)){return b;}omoPass(base);}if(i<3){sleep(600);}}throw new Error('页面获取失败：'+(last?(last.status||last.error||'空响应'):'无响应'));}
function omoOrigin(u){var m=/^(https?:\/\/[^\/]+)/i.exec(String(u||''));return m?m[1]:OMO_SITE;}
function omoDetail(ctx){var url=String((ctx.book&&ctx.book.bookUrl)||'');if(!url){throw new Error('书籍地址为空');}return page(omoGet(url,omoOrigin(url)),url);}
function omoToc(ctx){var url=String((ctx.book&&(ctx.book.tocUrl||ctx.book.bookUrl))||'');if(!url){throw new Error('目录地址为空');}return page(omoGet(url,omoOrigin(url)),url);}
function omoSearch(ctx){var base=omoNorm(ctx.base)||omoNorm(vars.get('server'))||OMO_SITE;var p=Number(ctx.page||1);var suffix=p>1?'----------'+p+'---.html':'-------------.html';var url=base+'/search/'+encodeURIComponent(ctx.key)+suffix;omoResponse(base+'/',3,9000);return page(omoGet(url,base),url);}
function omoPlayerData(h){var i=h.indexOf('var player_aaaa=');if(i<0){return null;}var st=h.indexOf('{',i);if(st<0){return null;}var dep=0;var end=-1;var q=0;for(var k=st;k<h.length;k++){var c=h.charCodeAt(k);if(q){if(c===92){k++;continue;}if(c===q){q=0;}continue;}if(c===34||c===39){q=c;continue;}if(c===123){dep++;}else if(c===125){dep--;if(dep===0){end=k+1;break;}}}if(end<0){return null;}try{return JSON.parse(h.substring(st,end));}catch(e){return null;}}
function omoContent(ctx){var url=String((ctx.chapter&&ctx.chapter.url)||'');var m0=/^(https?:\/\/[^\/]+)/i.exec(url);var base=m0?m0[1]:OMO_SITE;var html=omoGet(url,base);var pd=omoPlayerData(html);if(!pd){throw new Error('未找到播放数据（页面结构可能已变更）');}var raw=String(pd.url||'');if(String(pd.encrypt)==='1'){raw=native.urldecode(raw);}else if(String(pd.encrypt)==='2'){raw=native.unbase64(raw);}if(!raw){throw new Error('该集暂无播放地址');}var vd=pd.vod_data||{};var pic=String(vd.vod_pic||'');var ph='https://as.cfhls.top/';if(pic.indexOf('mac://')===0){var bare=pic.substring(6).replace(/^\/+/,'');var up=/(?:^|\/)upload\/.*$/i.exec(bare);pic=up?up[0].replace(/^\/+/,''):'https://'+bare.replace(/^([^\/]+)\/+/,'$1/');}if(pic.indexOf('//')===0){pic='https:'+pic;}if(/^https?:\/\//i.test(pic)){ph='';}else{pic=pic.replace(/^\/+/,'');}if(!pic){ph='';}var qs='url='+encodeURIComponent(raw)+'&dmid='+encodeURIComponent(String(pd.id||''))+'&next='+encodeURIComponent(String(pd.link_next||''))+'&name='+encodeURIComponent(String(vd.vod_name||''))+'&sid='+encodeURIComponent(String(pd.sid||'1'))+'&nid='+encodeURIComponent(String(pd.nid||'1'))+'&ph='+encodeURIComponent(ph)+'&h='+encodeURIComponent(base)+'&pic='+encodeURIComponent(pic);var purl=OMO_PLAYER+qs;var mm=null;for(var t=0;t<3;t++){var r=http.get(purl+(t?'&_r='+Date.now():''),{timeout:9000,headers:omoHeaders()});var txt=r.ok?String(r.body||''):'';mm=/playData\(\s*[\x27]([^\x27]+)[\x27]\s*,\s*[\x27]([^\x27]+)[\x27]\s*\)/.exec(txt);if(mm){break;}if(t<2){sleep(400);}}if(!mm){throw new Error('播放器解析繁忙，请稍后重试或切换线路');}var out='';try{out=native.fromBytes(native.decrypt('AES/CBC/PKCS7Padding',native.base64Bytes(mm[1]),native.bytes(OMO_KEY),native.hexBytes(mm[2])));}catch(e){throw new Error('播放地址解密失败：'+e.message);}out=String(out||'').replace(/^\s+|\s+$/g,'');if(out.indexOf('org.h://')===0){out='https://'+out.substring(8);}if(!/^https?:\/\//i.test(out)){throw new Error('解析出的播放地址异常');}return {video:out,videoPage:url};}
function omoCheck(ctx){var base=omoNorm(ctx.base)||OMO_SITE;var home=omoResponse(base+'/',3,9000);if(!home||!home.ok||!home.body){return '✖ 线路不可用：'+(home?(home.status||home.error||'空响应'):'无响应');}var hb=String(home.body);if(hb.length<20000){return '⚠ 线路响应异常（'+hb.length+' 字节），建议切换线路';}var u=base+'/search/'+encodeURIComponent('仙逆')+'-------------.html';var r=omoResponse(u,2,9000);if(!r||!r.ok){return '⚠ 首页正常，但搜索请求失败：'+(r?(r.status||r.error):'无响应');}if(omoShield(r.body)){var ok=omoPass(base);return ok?'✔ 线路可用；搜索触发了安全验证，已自动过盾（若仍失败请再试一次）':'⚠ 线路可用，但安全验证自动过盾失败，请稍后重试或切换线路';}return '✔ 线路可用，免登录，搜索正常';}

var XL_LINES = ['https://xanimu.ws','https://xanimu.one','https://xanimu.art','https://xanimu.net','https://xanimu.sbs','https://xanimu.top'];
var XL_ROAD = 'https://x99dh.github.io';
var XL_UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';
function xlNorm(u) {
  var s = String(u || '').replace(/^\s+|\s+$/g, '');
  if (!s) return '';
  if (s.indexOf('//') === 0) s = 'https:' + s;
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s.replace(/^\/+/, '');
  var m = /^(https?:\/\/[^\/?#]+)/i.exec(s);
  return m ? m[1].replace(/\/+$/, '') : '';
}
function xlAdd(list, u) {
  u = xlNorm(u);
  if (u && list.indexOf(u) < 0) list.push(u);
}
function xlMerged() {
  var out = [];
  for (var i = 0; i < XL_LINES.length; i++) xlAdd(out, XL_LINES[i]);
  try {
    var c = cache.get('xllines');
    if (c) {
      var p = JSON.parse(c);
      for (var j = 0; j < p.length; j++) xlAdd(out, p[j]);
    }
  } catch (e) {}
  try { xlAdd(out, vars.get('server')); } catch (e) {}
  return out;
}
function xlSiteOk(body) {
  return !!body && body.length > 30000 && body.indexOf('video-block') >= 0;
}
function xlLineOptions(ctx) {
  var list = xlMerged();
  try {
    var best = xlNorm(cache.get('xlbest'));
    if (best && list.indexOf(best) >= 0) {
      list.splice(list.indexOf(best), 1);
      list.unshift(best);
    }
  } catch (e) {}
  return list;
}
function xlPickHosts(body) {
  var out = [];
  if (!body) return out;
  var m = /encodedData\s*=\s*'([A-Za-z0-9+\/=]+)'/.exec(body);
  if (!m) return out;
  var raw = '';
  try { raw = native.unbase64(m[1]); } catch (e) { return out; }
  var rawJson = '';
  try { rawJson = decodeURIComponent(raw); } catch (e) { rawJson = raw; }
  var arr = null;
  try { arr = JSON.parse(rawJson); } catch (e) { return out; }
  if (!arr || !arr.length) return out;
  for (var i = 0; i < arr.length; i++) {
    var it = arr[i] || {};
    var urls = [];
    if (it.url) urls.push(it.url);
    if (it.urls) {
      for (var k = 0; k < it.urls.length; k++) {
        if (it.urls[k] && it.urls[k].url) urls.push(it.urls[k].url);
      }
    }
    var hit = false;
    for (var q = 0; q < urls.length; q++) {
      if (String(urls[q]).toLowerCase().indexOf('xanimu') >= 0) { hit = true; break; }
    }
    if (!hit) continue;
    for (var j = 0; j < urls.length; j++) {
      var h = xlNorm(urls[j]);
      if (h && /xanimu\.[a-z]+/i.test(h)) xlAdd(out, h);
    }
  }
  return out;
}
function xlFromRoad(ctx) {
  var road = '';
  try { road = xlNorm(vars.get('road')); } catch (e) {}
  if (!road) road = XL_ROAD;
  var tried = [road.replace('https://', '').replace('http://', '')];
  var r = http.get(road, { timeout: 12000, headers: { 'Accept': 'text/html,application/xhtml+xml,*/*;q=0.8', 'User-Agent': XL_UA } });
  if (!r.ok || !r.body) return '✖ 发布页读取失败（已尝试：' + tried.join(' / ') + '）';
  var hosts = xlPickHosts(r.body);
  if (!hosts.length) return '✖ 发布页没有解析到 xanimu 线路（已尝试：' + tried.join(' / ') + '）';
  cache.put('xllines', JSON.stringify(hosts), 3600);
  return '✔ 发布页解析到 ' + hosts.length + ' 条线路：' + hosts.map(function (x) { return x.replace('https://', ''); }).join(' ') + '\n重新打开书源设置即可选择';
}
function xlSpeedTest(ctx) {
  var list = xlMerged();
  var alive = [];
  var note = [];
  for (var i = 0; i < list.length; i++) {
    var t0 = new Date().getTime();
    var r = http.get(list[i] + '/zh-CN/', { timeout: 3500, headers: { 'User-Agent': XL_UA } });
    var ms = new Date().getTime() - t0;
    if (r.ok && xlSiteOk(r.body)) {
      alive.push({ url: list[i], ms: ms });
      note.push(list[i].replace('https://', '') + ' ' + ms + 'ms');
    } else {
      note.push(list[i].replace('https://', '') + ' 不可达');
    }
  }
  if (!alive.length) return '✖ 所有线路不可达\n' + note.join(' / ');
  alive.sort(function (a, b) { return a.ms - b.ms; });
  var best = alive[0].url;
  vars.set('server', best);
  cache.put('xlbest', best, 3600);
  try { ui.refreshExplore(); } catch (e) {}
  return '⚡ 已切换到最快线路 ' + best.replace('https://', '') + ' ' + alive[0].ms + 'ms\n' + note.join(' / ');
}
